rules = json.load(open('/app/re.json'))
fen = 'rn1qkbnr/ppp2ppp/8/4p3/4P3/5Q2/PPP2PPP/RNB1KB1R w KQkq - 0 6'
def has_cast():
    return any('RNB2B1R' in ln or 'RNB1KBR' in ln for ln in fen.split(chr(10)))
prev=''
for i,(p,r) in enumerate(rules):
    fen = re.sub(p, r, fen)
