    if has_cast():
        lines = [ln for ln in fen.split(chr(10)) if 'RNB2B1R' in ln or 'RNB1KBR' in ln]
        if lines != prev:
            prev = lines
            print(f'i={i} {p[:60]!r}')
            for ln in lines:
                print('    ', repr(ln))
